alter table public.stores enable row level security;
create policy stores_public_read on public.stores for select using(status='active' or public.is_store_member(id));
alter table public.products enable row level security;
create policy products_public_read on public.products for select using(status='active' and exists(select 1 from public.stores s where s.id=store_id and s.status='active') or public.is_store_member(store_id));
alter table public.categories enable row level security;
create policy categories_public_read on public.categories for select using(is_active and public.is_store_member(store_id) or (is_active and exists(select 1 from public.stores s where s.id=store_id and s.status='active')));
alter table public.product_variants enable row level security;
create policy variants_public_read on public.product_variants for select using(is_active and public.is_store_member(store_id) or (is_active and exists(select 1 from public.stores s where s.id=store_id and s.status='active')));
alter table public.brands enable row level security;
create policy brands_public_read on public.brands for select using(is_active and exists(select 1 from public.stores s where s.id=store_id and s.status='active'));
create policy brands_store_manage on public.brands for all using(public.is_store_member(store_id)) with check(public.is_store_member(store_id));
create policy products_store_manage on public.products for all using(public.is_store_member(store_id)) with check(public.is_store_member(store_id));
create policy categories_store_manage on public.categories for all using(public.is_store_member(store_id)) with check(public.is_store_member(store_id));
create policy variants_store_manage on public.product_variants for all using(public.is_store_member(store_id)) with check(public.is_store_member(store_id));
create policy product_media_public_read on public.product_media for select using(exists(select 1 from public.products p join public.stores s on s.id=p.store_id where p.id=product_id and p.store_id=product_media.store_id and p.status='active' and s.status='active'));
create policy product_media_store_manage on public.product_media for all using(public.is_store_member(store_id)) with check(public.is_store_member(store_id));
create policy product_options_store_manage on public.product_options for all using(public.is_store_member(store_id)) with check(public.is_store_member(store_id));
alter table public.orders enable row level security;
create policy orders_customer_read on public.orders for select using(user_id=public.current_user_id() or public.is_store_member(store_id));
